import{_ as t,o,c as r,aw as e,j as l,a as i}from"./chunks/framework.DLufY-ao.js";const c=JSON.parse('{"title":"HTTP Methods","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/http/2-http-methods.md","filePath":"wiki/dev-commit/network/network/http/2-http-methods.md"}'),u={name:"wiki/dev-commit/network/network/http/2-http-methods.md"};function s(n,a,d,T,p,h){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="http-methods" tabindex="-1">HTTP Methods <a class="header-anchor" href="#http-methods" aria-label="Permalink to &quot;HTTP Methods&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>HTTP-методы</strong> - последовательность из любых символов, кроме управляющих и разделителей, указывающая на основную операцию над ресурсом</li></ul></div><h2 id="запросы" tabindex="-1">Запросы <a class="header-anchor" href="#запросы" aria-label="Permalink to &quot;Запросы&quot;">​</a></h2><ul><li><strong>Идемпотентный метод</strong> - метод HTTP является идемпотентным, если повторный идентичный запрос, сделанный один или несколько раз подряд, имеет один и тот же эффект, не изменяющий состояние сервера</li><li>Идемпотентный метод не должен иметь никаких побочных эффектов (side-effects), кроме сбора статистики или подобных операций</li><li>Примеры: GET, PUT, DELETE, HEAD</li><li><strong>Неидемпотентный метод</strong> - противоположный идемпотентному</li><li>Примеры: POST</li></ul><hr><ul><li>Payload включается в тело запроса</li><li>✅ - есть кэширование</li><li>🅾️ - нет кэширования</li></ul><p>GET</p><p>✅ /api/user</p><ul><li>Получить информацию обо всех пользователях</li><li>Получить содержимое ресурса</li></ul><h4 id="варианты-get" tabindex="-1">Варианты GET <a class="header-anchor" href="#варианты-get" aria-label="Permalink to &quot;Варианты GET&quot;">​</a></h4><ul><li>/api/users - Получить информацию обо всех пользователях</li><li>/api/user/{user_id} - Получить информацию о пользователе с указанным ID</li><li>/api/users?status=active&amp;sort=desc - Получить информацию обо всех пользователях с заданием дополнительных Query Parameters</li></ul><p>К GET-запросу в теории можно добавить BODY, но для этого лучше использовать POST</p><p>POST</p><p>🅾️ /api/users</p><ul><li>Добавить нового пользователя</li><li>Создать новый ресурс и передать пользовательские данные в виде payload: <code>{ id: 1, name: &#39;Jack&#39;, age: 23 }</code></li><li>Метод предполагает, что по указанному URI будет производиться обработка передаваемого клиентом содержимого</li><li>Если был создан ресурс, то серверу следует вернуть ответ 201 (Created) с указанием URI нового ресурса в заголовке Location</li></ul><p>PUT</p>',16),l("p",{user_id:""},"🅾️ /api/user/",-1),l("ul",null,[l("li",null,"Заменить ВСЮ информацию о пользователе с указанным ID"),l("li",null,"Full Update"),l("li",null,[i("Обновить существующий ресурс (или создать новый, если его нет) и передать пользовательские данные в виде payload: "),l("code",null,"{ name: 'Jack', age: 23 }")]),l("li",null,"Если не передать одно из полей - оно будет null"),l("li",null,"В PUT содержится новая версия ресурса целиком"),l("li",null,"Метод предполагает, что загружаемое содержимое соответствует находящемуся по данному URI ресурсу"),l("li",null,"Если по заданному URI не существует ресурса, то сервер создаёт его и возвращает статус 201 (Created)")],-1),l("p",null,"PATCH",-1),l("p",{user_id:""},"🅾️ /api/user/",-1),l("ul",null,[l("li",null,"Обновить ЧАСТИЧНУЮ информацию о пользователе с указанным ID"),l("li",null,"Partial Update"),l("li",null,"Аналогичен PUT"),l("li",null,[i("Обновить ФРАГМЕНТ существующего ресурса и передать пользовательские данные в виде payload: "),l("code",null,"{ name: 'Tony' }")]),l("li",null,"Передавать можно только необходимые поля. Остальные поля останутся без изменения")],-1),l("p",null,"DELETE",-1),l("ul",null,[l("li",{user_id:""},[l("p",null,"/api/user/")]),l("li",null,[l("p",null,"Удалить пользователя с указанным ID")]),l("li",null,[l("p",null,"Удалить существующий ресурс")])],-1),e('<p>HEAD</p><h2 id="✅" tabindex="-1">✅ <a class="header-anchor" href="#✅" aria-label="Permalink to &quot;✅&quot;">​</a></h2><ul><li>Аналогичен GET, но в ответе сервера отсутствует тело</li><li>Проверка наличия ресурса. Получение информации о ресурсе, не получая самого ресурса</li><li>Обычно применяется для извлечения метаданных, проверки наличия ресурса (валидация URL) и чтобы узнать, не изменился ли он с момента последнего обращения. Заголовки ответа могут кэшироваться. При несовпадении метаданных ресурса с соответствующей информацией в кэше - копия ресурса помечается как устаревшая</li></ul><p>OPTIONS</p><h2 id="🅾️" tabindex="-1">🅾️ <a class="header-anchor" href="#🅾️" aria-label="Permalink to &quot;🅾️&quot;">​</a></h2><ul><li>Определение возможностей веб-сервера или параметров соединения для конкретного ресурса</li><li>В ответ сервер присылает заголовок Allow со списком поддерживаемых HTTP-методов</li></ul><p>TRACE</p><ul><li>Возвращает полученный запрос так, что клиент может увидеть, какую информацию промежуточные серверы добавляют или изменяют в запросе</li></ul><p>CONNECT</p><ul><li>Преобразует соединение запроса в прозрачный TCP/IP-туннель, обычно чтобы содействовать установлению защищённого SSL-соединения через нешифрованный прокси</li></ul><h2 id="отличия" tabindex="-1">Отличия <a class="header-anchor" href="#отличия" aria-label="Permalink to &quot;Отличия&quot;">​</a></h2><h4 id="get-vs-post" tabindex="-1">GET vs POST <a class="header-anchor" href="#get-vs-post" aria-label="Permalink to &quot;GET vs POST&quot;">​</a></h4><ul><li>GET может кешироваться браузером. GET идемпотентный: сколько бы раз не запрашивали в Google некоторый запрос, Google вернет тот же результат</li><li>POST не кешируется браузером. POST не идемпотентный: он может вставлять в базу новую строку каждый раз</li></ul><h4 id="post-vs-put" tabindex="-1">POST vs PUT <a class="header-anchor" href="#post-vs-put" aria-label="Permalink to &quot;POST vs PUT&quot;">​</a></h4><ul><li>POST предполагает, что по указанному URI будет производиться обработка передаваемого клиентом содержимого. POST не идемпотентный - отправка одних и тех же запросов POST несколько раз может привести к созданию нескольких ресурсов</li><li>PUT предполагает, что загружаемое содержимое соответствует находящемуся по данному URI ресурсу. PUT идемпотентный</li></ul><h4 id="put-vs-patch" tabindex="-1">PUT vs PATCH <a class="header-anchor" href="#put-vs-patch" aria-label="Permalink to &quot;PUT vs PATCH&quot;">​</a></h4><ul><li>PUT - замена. Необходимо передавать полный список полей, в отсутствующие поля будет записан null</li><li>PATCH - обновление. Можно обновлять части уже существующего объекта. Он не будет обновлять отсутствующие поля</li></ul><h2 id="crud" tabindex="-1">CRUD <a class="header-anchor" href="#crud" aria-label="Permalink to &quot;CRUD&quot;">​</a></h2><ul><li><strong>CRUD</strong> - акроним, обозначающий четыре базовые функции, используемые при работе с базами данных: Create (создание), Read (чтение), Update (модификация), Delete (удаление)</li><li>В системах, реализующих доступ к базе данных через API в стиле REST, эти функции реализуются зачастую (но не обязательно) через HTTP-методы PUT, POST, GET, PATCH, DELETE</li></ul>',19)])])}const _=t(u,[["render",s]]);export{c as __pageData,_ as default};
